export function guideCardsHTML(){return `<div class="guide-cards"><a href="/lenses/kak-vybrat-linzy"><span class="eyebrow">ПОНЯТНО О ЛИНЗАХ</span><h2>Как правильно выбрать линзы</h2><p>Рецепт, повседневные задачи, толщина и покрытия.</p><span class="text-button">Читать руководство ↗</span></a><a href="/lenses/progressivnye-linzy"><span class="eyebrow">НЕСКОЛЬКО ДИСТАНЦИЙ</span><h2>Прогрессивные очки</h2><p>Как работают зоны зрения и что важно при подборе.</p><span class="text-button">Узнать больше ↗</span></a></div>`;}
export function guidePageHTML(path,{preview=false}={}){const p=guidePages[path];if(p?.service)return servicePageHTML(p,{preview});return `<article class="lens-guide wrap" itemscope itemtype="https://schema.org/Article"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a><span>/</span><a href="/lenses">Линзы</a><span>/</span><span aria-current="page">${path.endsWith('progressivnye-linzy')?'Прогрессивные линзы':'Выбор линз'}</span></nav><header><p class="eyebrow">ЗРЕНИЕ В ПОВСЕДНЕВНОЙ ЖИЗНИ</p><h1 itemprop="headline">${p.heading}</h1><p class="guide-lead" itemprop="description">${p.intro}</p></header><details class="guide-contents" open><summary>Содержание · перейти к нужному вопросу</summary><nav class="guide-toc" aria-label="Содержание статьи">${p.sections.map(s=>`<a href="#${s[0]}">${s[1]}</a>`).join('')}</nav></details><div class="guide-body" itemprop="articleBody">${p.sections.map(s=>`<section id="${s[0]}"><h2>${s[1]}</h2>${illustratedSection(s[0],s[2])}</section>`).join('')}</div><aside class="guide-cta"><h2>Подберём линзы под ваши задачи</h2><p>На консультации обсудим рецепт, рабочие расстояния и подходящие варианты.</p><button class="button" data-booking>Записаться на подбор линз</button><p><a href="/lenses">Все виды линз</a> · <a href="${path.endsWith('progressivnye-linzy')?'/lenses/kak-vybrat-linzy':'/lenses/progressivnye-linzy'}">${path.endsWith('progressivnye-linzy')?'Как выбрать линзы':'О прогрессивных линзах'}</a></p></aside></article>`;}
